async () => {
  const errs = []; window.addEventListener('error', e => errs.push(e.message));
  const wait = () => new Promise(r => setTimeout(r, 60));
  const groups = [...document.querySelectorAll('#variant-toggle .vg')].map(g => ({t: g.querySelector('.lab').textContent, n: g.querySelectorAll('button').length, nc: g.querySelectorAll('button.nocalc').length}));
  const picks = ['btc4h_trail','g85b','g105','p05:p05-a45-u25k','p05:p05-a15-u10k','p07a:h4-900','p07a:h9-pause30','p07a:h9-cap3','p07a:h9r-k1','p07b:h2-00136','p07b:h13-gone90wallk0','p07b:h9r-s3','p07b:h9-pause30','p07a:h6-before'];
  const res = [];
  for (const period of ['augsep','aug','sep']) {
    document.querySelector(`#period-toggle button[data-period='${period}']`).click(); await wait();
    for (const k of picks) {
      const b = document.querySelector(`#variant-toggle button[data-variant='${k}']`);
      if (!b) { res.push([k,'NO BUTTON']); continue; }
      try { b.click(); } catch (e) { errs.push(k + ': ' + e.message); }
      await wait();
      if (period === 'augsep' || period==='aug') res.push([period, k, b.getAttribute('aria-pressed'), document.querySelector('#cfg-body .badge')?.textContent, document.querySelector('#kpi-grid .kpi-tile .kpi-value')?.textContent || document.querySelector('#kpi-grid .kpi-label')?.textContent.slice(0,50), document.querySelector('#coins-table tbody')?.textContent.slice(0,60)]);
    }
  }
  // rating click
  window.scrollTo(0, 3000);
  const tr = document.querySelector('#rating-table tr[data-key]'); tr.click(); await new Promise(r => setTimeout(r, 800));
  const sel = document.querySelector('#variant-toggle button[aria-pressed=true]')?.dataset.variant;
  // approach status
  document.querySelector(`#variant-toggle button[data-variant='btc4h_trail']`).click(); await wait();
  const upMain = [...document.querySelectorAll('#cfg-body dt')].find(d => d.textContent==='Подходов до')?.nextElementSibling.querySelector('.badge')?.textContent;
  document.querySelector(`#variant-toggle button[data-variant='g85']`).click(); await wait();
  const upG85 = [...document.querySelectorAll('#cfg-body dt')].find(d => d.textContent==='Подходов до')?.nextElementSibling.querySelector('.badge')?.textContent;
  return {groups, errs, res, rating: [tr.dataset.key, sel, window.scrollY], upMain, upG85};
}

